const SIZE_MAP: Record<string, string> = {
  xs: 'h-4 w-4',
  sm: 'h-5 w-5',
  md: 'h-6 w-6',
  lg: 'h-8 w-8',
  xl: 'h-12 w-12',
};

export const KainaraLogo: React.FC<KainaraLogoProps> = ({
  size,
  variant = 'gradient',
  className = '',
  ariaLabel = 'KAINARA logo',
  role = 'img',
  ...props
}) => {
  const reactId = useId();
  const gradientId = `kainara-logo-grad-${reactId.replace(/[:]/g, '')}`;

  const isNumericSize = typeof size === 'number';
  const sizeClass = typeof size === 'string' ? SIZE_MAP[size] || '' : '';

  return (
    <svg
      viewBox="0 0 100 100"
      width={isNumericSize ? size : undefined}
      height={isNumericSize ? size : undefined}
      className={`shrink-0 select-none ${sizeClass} ${className}`.trim()}
      role={role}
      aria-label={ariaLabel}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      {variant === 'gradient' ? (
        <>
          <defs>
            <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" style={{ stopColor: 'var(--kainara-logo-grad-start, #08705b)' }} />
              <stop offset="55%" style={{ stopColor: 'var(--kainara-logo-grad-mid, #0e9f6e)' }} />
              <stop offset="100%" style={{ stopColor: 'var(--kainara-logo-grad-end, #18b9d2)' }} />
            </linearGradient>
          </defs>
          <path d={KAINARA_PATH} fill={`url(#${gradientId})`} />
        </>
      ) : (
        <path d={KAINARA_PATH} fill="currentColor" />
      )}
    </svg>
  );
};

export default KainaraLogo;
